async function reserve(id) {
  const changed = await db.execute(
    "UPDATE inventory SET stock = stock - 1 WHERE id = ? AND stock > 0", [id]
  );
  return changed.rowCount === 1;
}

function discountRate(user, order, coupon) {
  const hasValidCoupon = coupon && !coupon.expired;
  if (!user.vip) {
    if (hasValidCoupon) return 0.95;
    return 1;
  }
  if (order.total > 1000) {
    if (hasValidCoupon) return 0.7;
    return 0.8;
  }
  return 0.9;
}
